import re
import os
import subprocess


def task_func(dir_path, exe_pattern, execute_files=True):
    results = []

    if not isinstance(dir_path, str) or not os.path.isdir(dir_path):
        return results

    pattern = re.compile(exe_pattern)

    try:
        entries = sorted(os.listdir(dir_path))
    except OSError:
        return results

    for name in entries:
        file_path = os.path.join(dir_path, name)

        if not os.path.isfile(file_path):
            continue

        if not os.access(file_path, os.X_OK):
            continue

        if pattern.search(name) is None:
            continue

        if execute_files:
            try:
                completed = subprocess.run(
                    [file_path],
                    capture_output=True,
                    text=True,
                    check=False,
                )
                results.append(completed.stdout)
            except Exception:
                results.append("")
        else:
            results.append(file_path)

    return results
